import {profileOperations} from './drawings/machining-model.mjs';
const round=n=>+n.toFixed(6);
function validate(options){if(![options.stockLength,options.kerf,options.endTrim].every(Number.isFinite)||options.stockLength<=0||options.kerf<0||options.endTrim<0||options.endTrim*2>=options.stockLength)throw Error('הגדרות מלאי מוטות לא תקינות');const ids=new Set;for(const s of options.stockBars){if(!s.id||ids.has(s.id)||s.id==='REFERENCE'||!s.profile||!s.material||!Number.isInteger(s.qty)||s.qty<0||!(s.length>2*options.endTrim))throw Error('רשומת מלאי מוט לא תקינה');ids.add(s.id);}}
export function planBars(parts,settings={}){const options={stockLength:12000,kerf:3,endTrim:0,stockBars:[],allowNewBars:true,...settings};validate(options);const ids=new Set,rejected=[],groups=new Map;
 for(const p of parts.filter(p=>!p.plate)){try{if(ids.has(p.id))throw Error('חלק כפול');ids.add(p.id);const ops=profileOperations(p),allowance=p.cuttingAllowance??0;if(!Number.isFinite(allowance)||allowance<0||p.warnings?.length)throw Error('אזהרת חלק או תוספת חיתוך לא תקינה');const item={id:p.id,mark:p.mark,profile:p.profile,material:p.material,length:ops.length,allowance,cutLength:ops.length+allowance};const k=p.profile+'|'+p.material;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(item);}catch(e){rejected.push({id:p.id,reason:e.message});}}
 const bars=[],used=new Map;for(const list of groups.values()){const remaining=[...list].sort((a,b)=>b.cutLength-a.cutLength||a.id.localeCompare(b.id));while(remaining.length){const first=remaining[0],stock=options.stockBars.filter(s=>s.profile===first.profile&&s.material===first.material&&(used.get(s.id)||0)<s.qty).map(s=>({...s,priority:s.priority??0}));if(options.allowNewBars)stock.push({id:'REFERENCE',length:options.stockLength,priority:100});let choice;
 for(const s of stock){const capacity=s.length-options.endTrim*2+options.kerf;let states=[{used:0,indices:[]}];for(let i=0;i<remaining.length;i++){const cost=remaining[i].cutLength+options.kerf,next=states.filter(x=>x.used+cost<=capacity+1e-6).map(x=>({used:x.used+cost,indices:[...x.indices,i]}));const all=[...states,...next],bins=new Map;for(const v of all){const k=Math.floor(v.used/Math.max(.1,capacity/2048));if(!bins.has(k)||v.used>bins.get(k).used)bins.set(k,v);}states=[...bins.values()].sort((a,b)=>b.used-a.used).slice(0,256);if(!states.some(x=>x.used===0))states.push({used:0,indices:[]});}const best=states.filter(x=>x.indices.length).sort((a,b)=>b.used-a.used||a.indices.length-b.indices.length)[0];if(!best)continue;const score=[s.priority,(capacity-best.used)/s.length,s.length];if(!choice||score.some((v,i)=>v<choice.score[i]&&score.slice(0,i).every((q,j)=>q===choice.score[j])))choice={stock:s,pattern:best,score};}
 if(!choice){const bad=remaining.shift();rejected.push({id:bad.id,reason:'אין מוט במלאי המתאים לאורך, לחומר ולחתך',length:bad.cutLength});continue;}const chosen=new Set(choice.pattern.indices),items=remaining.filter((_,i)=>chosen.has(i));for(let i=remaining.length-1;i>=0;i--)if(chosen.has(i))remaining.splice(i,1);used.set(choice.stock.id,(used.get(choice.stock.id)||0)+1);let at=options.endTrim;const placements=items.map((item,i)=>{const start=at,end=at+item.cutLength,cutRequired=i<items.length-1||end<choice.stock.length-1e-6;at=cutRequired?Math.min(end+options.kerf,choice.stock.length):end;return {...item,start:round(start),end:round(end),sawEnd:round(at),cutRequired,kerfUsed:round(at-end)};});bars.push({id:'BAR-'+(bars.length+1),stockId:choice.stock.id,stockLength:choice.stock.length,profile:first.profile,material:first.material,startTrim:options.endTrim,endTrim:options.endTrim,kerf:options.kerf,items:placements,used:round(at),remaining:round(Math.max(0,choice.stock.length-options.endTrim-at)),offcutRequiresFacing:true});}}
 const result={method:'stock-aware-beam-search',options,bars,rejected,total:parts.filter(p=>!p.plate).length,placed:bars.reduce((n,b)=>n+b.items.length,0),stockConsumed:Object.fromEntries(used),netLength:bars.reduce((n,b)=>n+b.items.reduce((v,p)=>v+p.length,0),0),stockLength:bars.reduce((n,b)=>n+b.stockLength,0),optimal:false};verifyBarPlan(result,parts);return result;}
export function verifyBarPlan(plan,parts){const byId=new Map(parts.filter(p=>!p.plate).map(p=>[p.id,p])),seen=new Set,stock=new Map(plan.options.stockBars.map(s=>[s.id,s])),uses=new Map;for(const b of plan.bars){if(b.stockId!=='REFERENCE'){const s=stock.get(b.stockId);if(!s||s.profile!==b.profile||s.material!==b.material||s.length!==b.stockLength)throw Error('מוט אינו תואם למלאי');uses.set(s.id,(uses.get(s.id)||0)+1);if(uses.get(s.id)>s.qty)throw Error('חריגה מכמות מלאי');}else if(!plan.options.allowNewBars||b.stockLength!==plan.options.stockLength)throw Error('שימוש במלאי ייחוס לא מאושר');if(b.kerf!==plan.options.kerf||b.startTrim!==plan.options.endTrim||b.endTrim!==plan.options.endTrim)throw Error('הגדרות חיתוך שונו');let at=b.startTrim;for(const item of b.items){const p=byId.get(item.id);if(!p||seen.has(item.id)||p.profile!==b.profile||p.material!==b.material)throw Error('חלק כפול או ערבוב חומר וחתך');seen.add(item.id);const length=profileOperations(p).length+(p.cuttingAllowance??0);if(Math.abs(length-item.cutLength)>.00001||Math.abs(item.start-at)>.00001||Math.abs(item.end-item.start-length)>.00001||Math.abs(item.sawEnd-(item.cutRequired?Math.min(item.end+b.kerf,b.stockLength):item.end))>.00001||Math.abs(item.kerfUsed-(item.sawEnd-item.end))>.00001||!item.cutRequired&&Math.abs(item.end-b.stockLength)>.00001)throw Error('אורך או מיקום חיתוך אינם תואמים למקור');at=item.sawEnd;}if(at>b.stockLength+.00001||b.items.at(-1).end>b.stockLength-b.endTrim+.00001||Math.abs(b.remaining-Math.max(0,b.stockLength-b.endTrim-at))>.00001)throw Error('חריגת אורך או שארית שגויה');}if(seen.size+plan.rejected.length!==plan.total)throw Error('ספירת חלקי חיתוך אינה תואמת');return true;}
